26 contract TokenStaking {
27     /* ----------------------------- Constants ----------------------------- */
28 
29     /// @dev 20% APR as "reward tokens per staked token per second", scaled by 1e18.
30     ///      0.20e18 / 31,536,000s (365 days) = 6,341,958,396
31     uint256 public constant REWARD_RATE_PER_SECOND = 6_341_958_396;
